#!/usr/bin/env bash
set -euo pipefail

# ──────────────────────────────────────────────
# a 3d chess game with 3d pieces and board, an AI opponent, and the full rules of chess — Startup Script
# Generated by Veronica (VACA)
#
# Builds the Go binary (if needed) and runs it.
# Passes any CLI arguments through to the binary.
# ──────────────────────────────────────────────

BINARY="a-3d-chess-game-with-3d-pieces-and-board-an-ai-opponent-and-the-full-rules-of-chess"
BUILD_DIR="./dist"
BINARY_PATH="${BUILD_DIR}/${BINARY}"

# Colors for output (using tput for portability)
GREEN=$(tput setaf 2 2>/dev/null || echo '')
CYAN=$(tput setaf 6 2>/dev/null || echo '')
YELLOW=$(tput setaf 3 2>/dev/null || echo '')
NC=$(tput sgr0 2>/dev/null || echo '')

echo ""
echo "${CYAN}════════════════════════════════════════════${NC}"
echo "${CYAN}  🚀 a 3d chess game with 3d pieces and board, an AI opponent, and the full rules of chess${NC}"
echo "${CYAN}════════════════════════════════════════════${NC}"
echo ""

# Build the binary if it doesn't exist or if source changed
if [ ! -f "${BINARY_PATH}" ] || [ "$(find . -name '*.go' -newer "${BINARY_PATH}" 2>/dev/null | head -1)" != "" ]; then
  echo "${YELLOW}🔨 Building...${NC}"
  mkdir -p "${BUILD_DIR}"
  go build -o "${BINARY_PATH}" .
  echo "${GREEN}✅ Build complete: ${BINARY_PATH}${NC}"
  echo ""
fi

# Run the binary with any passed arguments
echo "${CYAN}▶️  Starting ${BINARY}...${NC}"
echo "${CYAN}─────────────────────────────────────────────${NC}"
echo ""
exec "${BINARY_PATH}" "$@"
